/* =====================================================================
   MÓDULOS ADICIONALES
   ===================================================================== */
const EXTRA_ACT={},EXTRA_FORM={},EXTRA_CHANGE={};
const proxDia=d=>{const t=today();let f=new Date(t.getFullYear(),t.getMonth(),Math.min(d,lastDay(t.getFullYear(),t.getMonth())));if(f<t)f=new Date(t.getFullYear(),t.getMonth()+1,Math.min(d,lastDay(t.getFullYear(),t.getMonth()+1)));return f};
async function useCap(n){try{return window.claude&&window.claude.use?await window.claude.use(n):null}catch(e){return null}}
async function mcpCall(server,tool,input){const mcp=await useCap('mcp');if(!mcp)throw{code:'no_mcp'};const r=await mcp.callTool(server,tool,input);return r.payload}
const digits=s=>String(s||'').replace(/\D/g,'');

/* ---------------- 1. Tarjetas de crédito ---------------- */
function cortesDesde(t,fecha,hasta){const c=+t.corte||25;let n=0;let d=parse(fecha);let cur=new Date(d.getFullYear(),d.getMonth(),Math.min(c,lastDay(d.getFullYear(),d.getMonth())));if(cur<=d)cur=new Date(d.getFullYear(),d.getMonth()+1,Math.min(c,lastDay(d.getFullYear(),d.getMonth()+1)));while(cur<=hasta&&n<600){n++;cur=new Date(cur.getFullYear(),cur.getMonth()+1,Math.min(c,lastDay(cur.getFullYear(),cur.getMonth()+1)))}return n}
function compraEstado(t,c,hasta=today()){const n=Math.max(1,+c.cuotas||1),i=n>1?(+t.tasa||0)/100:0;const cuota=annuity(+c.valor,i,n);let k=c.pagada?n:Math.min(cortesDesde(t,c.fecha,hasta),n);let saldo=+c.valor;for(let j=0;j<k;j++){const int=saldo*i;saldo=Math.max(0,saldo-(cuota-int))}if(c.pagada)saldo=0;return{cuota,n,k,saldo,int:cuota*n-c.valor,pendiente:k<n&&!c.pagada}}
function tarjetaPagoMes(t,offset=0){const ref=addMonths(today(),offset);return (t.compras||[]).reduce((a,c)=>{const e=compraEstado(t,c,ref);return a+(e.pendiente?e.cuota:0)},0)}
function tarjetasDeuda(){return(S.tarjetas||[]).reduce((a,t)=>a+(t.compras||[]).reduce((b,c)=>b+compraEstado(t,c).saldo,0),0)}
let TSEL=null,TSIM={v:1200000,t:2.1};
V.tarjetas=()=>{const T=S.tarjetas;if(!T.find(x=>x.id===TSEL))TSEL=T[0]?.id;const cur=T.find(x=>x.id===TSEL);const deuda=tarjetasDeuda(),pm=T.reduce((a,t)=>a+tarjetaPagoMes(t),0),cupo=T.reduce((a,t)=>a+ +t.cupo,0);
  const simRows=[1,3,6,12,24,36].map(n=>{const c=annuity(TSIM.v,n>1?TSIM.t/100:0,n);return{n,c,int:c*n-TSIM.v}});
  let det=empty('credit-card','Agrega tu tarjeta para controlar el cupo, las fechas y cuánto te cuestan las compras a cuotas.',`<button class="btn pri" data-modal="tarjeta">${ic('plus')}Agregar tarjeta</button>`);
  if(cur){const cs=(cur.compras||[]).map(c=>({c,e:compraEstado(cur,c)}));const d1=cs.reduce((a,x)=>a+x.e.saldo,0),u=cur.cupo?d1/cur.cupo:0,pmc=tarjetaPagoMes(cur);
    det=`<div class="ph"><div style="display:flex;gap:12px;align-items:center"><span class="ri t-blue" style="width:48px;height:48px;border-radius:12px;display:grid;place-items:center">${ic('credit-card')}</span><div><h2>${esc(cur.nombre)}</h2><div class="note">${esc(entName(cur.entidad))} · corte el día ${cur.corte} · pago el día ${cur.pago} · ${(+cur.tasa).toLocaleString('es-CO')}% mensual</div></div></div><div style="display:flex;gap:8px"><button class="btn sm soft" data-modal="compraTC" data-id="${cur.id}">${ic('plus')}Compra</button><button class="btn sm ghost" data-act="delTC" data-id="${cur.id}" aria-label="Eliminar tarjeta">${ic('trash-2')}</button></div></div>
    <div class="grid g4" style="gap:10px"><div class="metric"><b class="neg">${$(d1)}</b><span>Debes en total</span></div><div class="metric"><b>${$(pmc)}</b><span>Pago mínimo del mes</span></div><div class="metric"><b>${$(Math.max(cur.cupo-d1,0))}</b><span>Cupo disponible</span></div><div class="metric"><b>${fshort(proxDia(+cur.pago))}</b><span>Próxima fecha de pago</span></div></div>
    <div><div class="track lg"><i style="width:${Math.min(u,1)*100}%;background:${u>.7?'var(--red)':u>.3?'#E08A00':'#9EDB4E'}"></i></div><div class="note" style="margin-top:4px">Usas el ${pct(u,0)} del cupo de ${$(cur.cupo)}. ${u>.3?'Lo ideal es no pasar del 30% para cuidar tu historial en las centrales de riesgo.':'¡Bien! Usar menos del 30% cuida tu historial crediticio.'}</div></div>
    ${pmc>0?`<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn pri" data-act="tcPagarTotal" data-id="${cur.id}">${ic('circle-check')}Pagué el total de la tarjeta</button><span class="note" style="align-self:center">Pagar el total cada mes evita casi todos los intereses.</span></div>`:''}
    <div class="tbl-wrap"><table><thead><tr><th>Compra</th><th>Fecha</th><th class="r">Valor</th><th>Cuotas</th><th class="r">Cuota mensual</th><th class="r">Intereses</th><th class="r">Te falta</th><th></th></tr></thead><tbody>${cs.map(({c,e})=>`<tr class="${e.saldo<=0?'done':''}"><td>${esc(c.desc)}</td><td class="nw">${fdate(parse(c.fecha))}</td><td class="r num">${$(c.valor)}</td><td>${e.k} de ${e.n}</td><td class="r num">${$(e.cuota)}</td><td class="r num ${e.int>0?'neg':''}">${$(e.int)}</td><td class="r num">${$(e.saldo)}</td><td class="r"><button class="btn icon sm ghost" data-act="delCompraTC" data-id="${cur.id}" data-cid="${c.id}" aria-label="Eliminar compra">${ic('trash-2')}</button></td></tr>`).join('')||'<tr><td colspan="8" class="note">Sin compras registradas.</td></tr>'}</tbody></table></div><p class="note">Suponemos que pagas al menos el mínimo cada mes. Las compras a una sola cuota no cobran intereses si pagas a tiempo.</p>`}
  return pageH('credit-card','b-blue','Tarjetas de crédito','Controla cuánto debes, el cupo que te queda, las fechas de corte y de pago, y cuánto te cuesta cada compra a cuotas.',`<button class="btn pri" data-modal="tarjeta">${ic('plus')}Agregar tarjeta</button>`)+`
  <section class="grid g3">${kpi('credit-card','t-red','Debes en tarjetas',$(deuda),T.length+' tarjetas','neg')}${kpi('calendar','t-amber','Pago mínimo de este mes',$(pm),'Suma de las cuotas que se cobran')}${kpi('gauge',cupo&&deuda/cupo>.3?'t-red':'t-green','Uso del cupo total',pct(cupo?deuda/cupo:0,0),'Lo sano: menos del 30%')}</section>
  <section class="grid g12"><div class="card" style="align-self:start"><h2>Mis tarjetas</h2><div class="list">${T.map(t=>{const d=(t.compras||[]).reduce((a,c)=>a+compraEstado(t,c).saldo,0);return `<div class="rowi" data-act="selTC" data-id="${t.id}" style="cursor:pointer;${t.id===TSEL?'background:var(--blue-soft)':''}"><span class="ri t-blue">${ic('credit-card')}</span><div class="rb"><div class="rt">${esc(t.nombre)}</div><div class="rs">${esc(entName(t.entidad))}</div><div class="track" style="margin-top:6px"><i style="width:${t.cupo?Math.min(d/t.cupo,1)*100:0}%;background:#1F2B4B"></i></div></div><div class="rv">${$(d)}</div></div>`}).join('')||'<p class="note">Aún no tienes tarjetas.</p>'}</div></div><div class="card">${det}</div></section>
  <div class="card"><h2 style="display:flex;gap:8px;align-items:center">${ic('calculator')}¿A cuántas cuotas difiero una compra?</h2><p class="note" style="font-size:14px">Mientras más cuotas, más pagas en intereses. Compara antes de pasar la tarjeta.</p><div class="form" style="grid-template-columns:repeat(auto-fit,minmax(200px,260px))">${field('Valor de la compra',money('tsv',TSIM.v,{attrs:'data-x="tsim" data-k="v"'}))}${field('Interés mensual de tu tarjeta (%)',num('tst',TSIM.t,{attrs:'data-x="tsim" data-k="t"'}),{tip:'Aparece en tu extracto como "tasa mes vencido" o "MV". En Colombia suele estar cerca del 2% mensual.'})}</div>
    <div class="tbl-wrap"><table><thead><tr><th>Cuotas</th><th class="r">Pagas cada mes</th><th class="r">Intereses en total</th><th class="r">Pagas en total</th></tr></thead><tbody>${simRows.map(r=>`<tr><td>${r.n===1?'1 (sin intereses)':r.n}</td><td class="r num">${$(r.c)}</td><td class="r num ${r.int>0?'neg':''}">${$(r.int)}</td><td class="r num"><b>${$(r.c*r.n)}</b></td></tr>`).join('')}</tbody></table></div></div>`};
M.tarjeta=()=>({t:'Agregar tarjeta de crédito',b:`<form id="mform" data-form="tarjeta" class="form">${field('Nombre para reconocerla',txt('nombre','',{req:true,ph:'Ej. Visa Bancolombia'}),{cls:'s2'})}${field('Banco',sel('entidad',entOpts(),'',{create:'ent',search:true,ph:'Elige el banco'}))}${field('Cupo total',money('cupo','',{req:true}),{tip:'El máximo que te deja gastar el banco. Aparece en tu extracto o en la app.'})}${field('Día de corte',num('corte',25),{tip:'El día en que el banco cierra la cuenta del mes. Las compras después de esa fecha pasan al mes siguiente.'})}${field('Día límite de pago',num('pago',10),{tip:'Hasta ese día puedes pagar sin intereses de mora.'})}${field('Interés mensual (%)',num('tasa',2.1),{hint:'Míralo en tu extracto como "tasa MV".'})}</form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar</button>`});
M.compraTC=ds=>({t:'Registrar compra con tarjeta',b:`<form id="mform" data-form="compraTC" data-id="${ds.id}" class="form">${field('¿Qué compraste?',txt('desc','',{req:true,ph:'Ej. Televisor',attrs:'data-autocat'}),{cls:'s2'})}${field('Valor',money('valor','',{req:true}))}${field('Fecha',datep('fecha',iso(today())))}${field('¿A cuántas cuotas?',num('cuotas',1),{cls:'full',hint:chips('cuotas',[1,3,6,12,24,36],1)})}${field('Categoría',sel('cat',catOpts(),'',{create:1,search:true,ph:'Se elige sola'}),{hint:'<span id="catHint"></span>'})}<label class="full" style="display:flex;gap:10px;align-items:center;font-size:14.5px"><input type="checkbox" class="switch" name="comoGasto" checked>Registrarla también en mis gastos del mes</label></form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar</button>`});
EXTRA_FORM.tarjeta=d=>{S.tarjetas.push({id:uid(),nombre:d.nombre,entidad:d.entidad,cupo:d.cupo,corte:Math.min(31,Math.max(1,Math.round(d.corte||25))),pago:Math.min(31,Math.max(1,Math.round(d.pago||10))),tasa:d.tasa||0,compras:[]});TSEL=S.tarjetas.at(-1).id;toast('Tarjeta agregada')};
EXTRA_FORM.compraTC=(d,f)=>{const t=S.tarjetas.find(x=>x.id===f.dataset.id);if(!d.valor){toast('Escribe el valor');return false}t.compras.push({id:uid(),fecha:d.fecha||iso(today()),desc:d.desc,valor:d.valor,cuotas:Math.max(1,Math.round(d.cuotas||1))});if(d.comoGasto)S.gastos.push({id:uid(),fecha:d.fecha||iso(today()),desc:d.desc,cat:d.cat||'Otros',valor:d.valor,quien:'familia',medio:'Tarjeta de crédito'});toast('Compra registrada')};
EXTRA_ACT.selTC=b=>{TSEL=b.dataset.id;render()};
EXTRA_ACT.tcPagarTotal=b=>{const t=S.tarjetas.find(x=>x.id===b.dataset.id);t.compras.forEach(c=>c.pagada=true);commit();render();toast('¡Tarjeta al día!')};
EXTRA_ACT.delCompraTC=b=>{const t=S.tarjetas.find(x=>x.id===b.dataset.id);t.compras=t.compras.filter(c=>c.id!==b.dataset.cid);commit();render()};
EXTRA_ACT.delTC=b=>{CONFIRM={fn:()=>{S.tarjetas=S.tarjetas.filter(x=>x.id!==b.dataset.id)}};openModal('confirm',{title:'¿Eliminar tarjeta?',msg:'Se borrará la tarjeta con sus compras registradas.'})};
EXTRA_CHANGE.tsim=el=>{TSIM[el.dataset.k]=el.dataset.money!==undefined?parseMoney(el.value):parseNum(el.value);render()};

/* ---------------- 2. Gastos desde el correo del banco ---------------- */
let MAIL={rows:null,state:'',q:''};
const MAILQ='(compra OR compraste OR transaccion OR transacción OR pago OR débito OR retiro) (from:bancolombia OR from:davivienda OR from:nequi OR from:daviplata OR from:bancodebogota OR from:nu.com.co OR from:scotiabankcolpatria OR from:bbva OR from:avvillas OR from:lulobank OR from:bancopopular OR from:bancodeoccidente OR from:falabella) newer_than:30d';
V.correo=()=>pageH('mail','b-blue','Gastos desde el correo del banco','Tu banco te envía un correo cada vez que pagas con tarjeta o haces una transferencia. Aquí los leemos de tu Gmail, la IA saca el valor y el comercio, y tú decides cuáles registrar.')+`
  <div class="card"><div class="grid g3" style="gap:10px">${[['mail-search','1. Buscamos','Correos de bancos y billeteras de los últimos 30 días.'],['sparkles','2. La IA los lee','Saca el valor, el comercio, la fecha y la categoría.'],['check-check','3. Tú confirmas','Eliges cuáles se registran. Nada se guarda sin tu visto bueno.']].map(([i,t,d])=>`<div class="metric"><b style="display:flex;gap:6px;align-items:center">${ic(i)}${t}</b><span>${d}</span></div>`).join('')}</div>
  <details><summary class="note" style="cursor:pointer">Búsqueda avanzada (opcional)</summary>${field('Filtro de Gmail',`<input class="inp" id="mailQ" value="${esc(MAIL.q||MAILQ)}">`,{hint:'Puedes agregar el remitente exacto de tu banco, por ejemplo from:notificaciones@banco.com'})}</details>
  <div><button class="btn pri" data-act="mailScan" ${MAIL.state==='buscando'?'disabled':''}>${ic('mail-search')}${MAIL.state==='buscando'?'Buscando…':'Buscar compras en mi correo'}</button></div>
  <p class="note">Usa tu conexión de Gmail en claude.ai. La primera vez te pedirá permiso. Solo se leen los correos que coinciden con la búsqueda.</p></div>
  ${MAIL.state==='nomcp'?alertBox('warn','cloud-off','No pude conectarme a tu Gmail','Abre el libro en claude.ai y asegúrate de tener Gmail conectado en tus conectores.'):''}${MAIL.state==='vacio'?alertBox('info','info','No encontré correos nuevos de compras','Prueba con la búsqueda avanzada, agregando el remitente exacto de tu banco.'):''}${MAIL.state==='error'?alertBox('bad','circle-x','Hubo un problema al leer el correo','Intenta de nuevo en un momento.'):''}
  ${MAIL.rows?`<div class="card"><div class="ph"><h2>Revisa antes de registrar</h2><span class="note">${MAIL.rows.filter(r=>r.incl).length} seleccionados</span></div><div class="tbl-wrap"><table><thead><tr><th></th><th>Fecha</th><th>Comercio</th><th class="r">Valor</th><th style="min-width:190px">Categoría</th><th>Hormiga</th></tr></thead><tbody>${MAIL.rows.map((r,i)=>`<tr><td><input type="checkbox" class="chk" data-x="mailrow" data-i="${i}" data-f="incl" ${r.incl?'checked':''} aria-label="Registrar"></td><td class="nw">${fdate(parse(r.fecha))}</td><td>${esc(r.desc)}<div class="note">${esc(r.asunto||'')}</div></td><td class="r num">${$(r.valor)}</td><td>${sel('mc'+i,catOpts(),r.cat,{attrs:`data-x="mailrow" data-i="${i}" data-f="cat"`,search:true})}</td><td><input type="checkbox" class="chk" data-x="mailrow" data-i="${i}" data-f="hormiga" ${r.hormiga?'checked':''} aria-label="Hormiga"></td></tr>`).join('')}</tbody></table></div><div><button class="btn pri" data-act="mailImport">${ic('check')}Registrar seleccionados</button></div></div>`:''}`;
EXTRA_ACT.mailScan=async()=>{MAIL.q=document.getElementById('mailQ')?.value||MAILQ;MAIL.state='buscando';MAIL.rows=null;render();let pay;try{pay=await mcpCall('Gmail','search_threads',{query:MAIL.q,pageSize:40})}catch(e){MAIL.state=e&&e.code==='no_mcp'?'nomcp':'error';render();return}
  const msgs=[];(pay?.threads||[]).forEach(t=>(t.messages||[]).forEach(m=>{if(!S.correoIds.includes(m.id))msgs.push({id:m.id,asunto:m.subject||'',snippet:m.snippet||'',fecha:m.date||'',de:m.sender||''})}));
  if(!msgs.length){MAIL.state='vacio';render();return}
  let rows=null;const sample=await useCap('sample');if(sample){try{const r=await sample.json(`Extrae compras, pagos o débitos de estas notificaciones bancarias colombianas. Ignora publicidad, ofertas, extractos y abonos/ingresos. Responde SOLO JSON: {"items":[{"i":0,"es_gasto":true,"fecha":"YYYY-MM-DD","comercio":"nombre corto","valor":12345}]}. Valor en pesos sin puntos. Si no hay fecha clara usa la del correo.\nCORREOS: ${JSON.stringify(msgs.map((m,i)=>({i,asunto:m.asunto,texto:m.snippet,fecha_correo:m.fecha,remitente:m.de})))}`,{modelTier:'quick'});rows=(r.items||[]).filter(x=>x.es_gasto&&+x.valor>0).map(x=>({mid:msgs[x.i]?.id,fecha:/^\d{4}-\d\d-\d\d$/.test(x.fecha)?x.fecha:iso(today()),desc:x.comercio||msgs[x.i]?.asunto||'Compra',valor:+x.valor,asunto:msgs[x.i]?.asunto}))}catch(e){}}
  if(!rows)rows=msgs.map(m=>{const mm=(m.asunto+' '+m.snippet).match(/\$\s?([\d\.\,]+)/);const v=mm?pnum(mm[1]):0;const d=new Date(m.fecha);return{mid:m.id,fecha:isNaN(d)?iso(today()):iso(d),desc:(m.snippet.match(/en ([A-Z0-9 \*\.]{3,30})/)||[])[1]||m.asunto||'Compra',valor:v,asunto:m.asunto}}).filter(r=>r.valor>0);
  rows.forEach(r=>{r.cat=localCat(r.desc)?.cat||'Otros';r.hormiga=localHormiga({desc:r.desc,valor:r.valor,cat:r.cat});r.incl=true});
  if(rows.length){const res=await aiClassify(rows);if(res)res.forEach(x=>{const r=rows[x.i];if(!r)return;if(x.cat&&!(x.cat==='Otros'&&localCat(r.desc)))r.cat=x.cat;if(x.hormiga!==null)r.hormiga=x.hormiga})}
  MAIL.rows=rows;MAIL.state=rows.length?'ok':'vacio';render()};
EXTRA_CHANGE.mailrow=el=>{const r=MAIL.rows[+el.dataset.i];r[el.dataset.f]=el.type==='checkbox'?el.checked:el.value};
EXTRA_ACT.mailImport=()=>{const sel2=MAIL.rows.filter(r=>r.incl);sel2.forEach(r=>{S.gastos.push({id:uid(),fecha:r.fecha,desc:r.desc,cat:r.cat,valor:r.valor,quien:'familia',medio:'Tarjeta',hormiga:!!r.hormiga,hormigaSrc:'ia'});if(r.mid)S.correoIds.push(r.mid)});S.correoIds=S.correoIds.slice(-800);MAIL.rows=null;MAIL.state='';commit();render();toast(`${sel2.length} gastos registrados desde tu correo`)};

/* ---------------- 3. Foto de la factura ---------------- */
async function leerFactura(file){const h=document.getElementById('fotoHint');const form=document.querySelector('#modal form[data-form="gasto"]');if(!form)return;const sample=S.cfg.ia.ocr===false?null:await useCap('sample');
  if(!sample){h.textContent=iaMsg();return}const lim=await sample.limits?.().catch(()=>null);if(lim&&!lim.images){h.textContent='Esta vista no permite enviar imágenes a la IA.';return}
  h.innerHTML=`<span class="pill vio">${ic('sparkles')}Leyendo la factura…</span>`;
  try{const r=await sample.json(`Lee esta factura o recibo colombiano. Responde SOLO JSON: {"comercio":"nombre corto","valor":12345,"fecha":"YYYY-MM-DD","categoria":"una de: ${S.cfg.categorias.map(c=>c.nombre).join(', ')}"}. "valor" es el TOTAL pagado en pesos, sin puntos. Si no hay fecha visible usa null.`,{images:[file],modelTier:'default'});
    if(r.comercio){form.querySelector('[name=desc]').value=r.comercio}if(+r.valor){const m=form.querySelector('[name=valor]');m.value=NF.format(Math.round(+r.valor))}
    if(r.fecha&&/^\d{4}-\d\d-\d\d$/.test(r.fecha))setDateValue(form,'fecha',r.fecha);if(r.categoria&&catOf(r.categoria)){setSelValue(form,'cat',catOf(r.categoria).nombre);form.dataset.catManual='1'}
    h.innerHTML=`<span class="pill ok">${ic('check')}Listo. Revisa los datos antes de guardar.</span>`;updatePreviews(document.getElementById('modal'));onAutoInput(form.querySelector('[name=desc]'))}catch(e){h.textContent='No pude leer la factura. Intenta con una foto más clara o escribe los datos.'}}
function setDateValue(form,name,v){const inp=form.querySelector(`input[type=hidden][name="${name}"]`);if(!inp)return;inp.value=v;const tv=inp.parentElement.querySelector('.tv');tv.className='tv';tv.innerHTML=`${ic('calendar')}<span>${fdate(parse(v))}</span>`}
document.addEventListener('change',e=>{if(e.target.id==='fotoFact'&&e.target.files[0])leerFactura(e.target.files[0])});

/* ---------------- 4. Recordatorios de cobro ---------------- */
function cobroMsg(L,tono){const e=engine(L),c=S.contactos.find(x=>x.id===L.contactoId)||{};const n=(c.nombre||'').split(' ')[0]||'';const yo=(S.perfil.nombre||'').split(' ')[0];const cu=e.vencidas.length?e.vencidas:[e.next].filter(Boolean);const tot=cu.reduce((a,r)=>a+r.valor,0);const fecha=cu[0]?fdate(cu[0].fecha):'';const conc=L.concepto?` del préstamo "${L.concepto}"`:'';
  if(tono==='amable')return `Hola ${n}, ¿cómo estás? Te escribo para recordarte la cuota${conc}: ${$(tot)}${e.vencidas.length?`, que tenía fecha del ${fecha}`:` para el ${fecha}`}. Quedan pendientes ${$(e.saldo)} en total. Cualquier cosa me cuentas. ¡Gracias!${yo?' '+yo:''}`;
  if(tono==='directo')return `Hola ${n}. Te recuerdo el pago${conc} por ${$(tot)} (${e.vencidas.length?`venció el ${fecha}`:`vence el ${fecha}`}). Saldo pendiente: ${$(e.saldo)}. ¿Me confirmas cuándo me lo puedes transferir? Gracias.`;
  return `Hola ${n}. El pago${conc} por ${$(tot)} está atrasado desde el ${fecha}${e.mora?` (${e.mora} días)`:''}. Necesito que lo pongamos al día lo antes posible. Saldo total pendiente: ${$(e.saldo)}. Por favor respóndeme hoy con la fecha de pago.`}
