  const acre=kind==='cobrar'?yo:otro,deu=kind==='cobrar'?otro:yo;const doc=new J({unit:'pt',format:'letter'}),W=612,Lm=56;let y=64;const T=(s,x,yy,o)=>doc.text(String(s).replace(/[^\x00-\xFF]/g,''),x,yy,o);
