M.gcal=()=>{const items=agenda().filter(x=>x.d>=0&&x.d<=45);return{wide:true,t:'Agregar pagos a Google Calendar',b:`<p class="note" style="font-size:14px;margin:0">Se crea un evento de todo el día con aviso un día antes. Los que ya agregaste aparecen marcados.</p><div class="list">${items.map((x,i)=>{const done=S.calIds[calKey(x)];return `<label class="rowi" style="cursor:pointer"><input type="checkbox" class="chk" data-gc="${i}" ${done?'disabled':'checked'}>${dateBox(x.fecha)}<div class="rb"><div class="rt">${esc(x.titulo)}</div><div class="rs">${esc(x.sub)} · ${$(x.monto)}</div></div>${done?'<span class="pill ok">Ya está</span>':''}</label>`}).join('')||'<p class="note">No hay pagos en los próximos 45 días.</p>'}</div>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" data-act="gcalGo">${ic('calendar-plus')}Agregar a mi calendario</button>`}};
