const RDOCS=[['cir','Certificado de ingresos y retenciones (formulario 220)','Te lo da tu empleador entre febrero y marzo.'],['banc','Certificados bancarios con saldos al 31 de diciembre','Cada banco lo genera en su app o página.'],['cdt','Certificados de rendimientos financieros y retención (CDT, fondos)','De cada entidad donde tengas inversiones.'],['cred','Certificados de deudas al 31 de diciembre','Créditos, tarjetas e hipoteca.'],['hip','Certificado de intereses pagados por crédito de vivienda','Son deducibles: pueden bajar tu impuesto.'],['pens','Certificados de aportes voluntarios a pensión o cuentas AFC','Pueden ser rentas exentas.'],['salud','Certificado de medicina prepagada o pólizas de salud','Deducción hasta un tope mensual.'],['dep','Datos de tus dependientes económicos','Hijos o personas a cargo: dan derecho a una deducción.'],['bienes','Valor de tus bienes (avalúo catastral, vehículo)','Del impuesto predial y vehicular.']];
V.renta=()=>{const y=RENTAY,uvt=+S.cfg.uvt[y]||0,R=S.renta[y]||(S.renta[y]={docs:{},consig:0,consumos:0});const T=totales(),ing=ingresoMensual()*12;const yr=String(y);const gas=S.gastos.filter(g=>g.fecha.startsWith(yr)).reduce((a,g)=>a+ +g.valor,0);const tc=S.tarjetas.reduce((a,t)=>a+(t.compras||[]).filter(c=>c.fecha.startsWith(yr)).reduce((b,c)=>b+ +c.valor,0),0);
  const rend=S.inversiones.reduce((a,x)=>a+inv(x).bruto,0),ret=S.inversiones.reduce((a,x)=>a+inv(x).ret,0);
  const crit=[['Ingresos brutos del año',ing,1400,'Lo que ganas en el año (salario, honorarios, arriendos…).'],['Patrimonio bruto al 31 de diciembre',T.A,4500,'Todo lo que tienes: cuentas, inversiones, casa, carro, lo que te deben.'],['Compras con tarjeta de crédito',tc,1400,'Total pagado con tarjetas de crédito en el año.'],['Compras y consumos totales',Math.max(gas,+R.consumos||0),1400,'Todo lo que gastaste en el año.'],['Consignaciones y depósitos bancarios',+R.consig||0,1400,'Todo lo que te entró a tus cuentas en el año. Escríbelo abajo.']].map(([l,v,u,d])=>({l,v,tope:u*uvt,u,d,pasa:uvt&&v>=u*uvt}));
  const debe=crit.some(c=>c.pasa),cerca=!debe&&crit.some(c=>c.v>=c.tope*.85);const nd=Object.values(R.docs).filter(Boolean).length;
  return pageH('file-check','b-pink','Asistente de declaración de renta','Te ayuda a saber si debes declarar renta ante la DIAN y a reunir los documentos. Es una orientación: para presentar la declaración apóyate en un contador o en el asistente de la DIAN.')+`
  <div class="card"><div class="form" style="grid-template-columns:repeat(auto-fit,minmax(220px,max-content))">${field('Año gravable',sel('ry',[{v:today().getFullYear()-1,l:`${today().getFullYear()-1} (declaras en ${today().getFullYear()})`},{v:today().getFullYear(),l:`${today().getFullYear()} (declaras en ${today().getFullYear()+1})`}],y,{attrs:'data-x="rentaY"'}))}${field(`Valor de la UVT ${y}`,money('ruvt',uvt,{attrs:`data-x="rentaUVT" data-y="${y}"`}),{tip:'La UVT es la unidad que usa la DIAN para fijar los topes. Para 2025 es $ 49.799 y para 2026 es $ 52.374. Verifica el valor oficial de cada año.'})}</div></div>
  <div class="verdict ${debe?'no':cerca?'cuidado':'si'}" style="border-radius:12px"><span class="vi">${ic(debe?'file-check':cerca?'triangle-alert':'circle-check')}</span><div><div class="lbl-s">${debe?'Con tus datos':'Con los datos que tienes'}</div><h2>${debe?'Sí, todo indica que debes declarar renta':cerca?'Estás cerca de los topes: revisa con cuidado':'Por ahora no superas los topes para declarar'}</h2><div class="note" style="font-size:14px">Basta con superar uno solo de los topes para estar obligado. ${S.perfil.digitos?`Tus últimos dígitos de cédula son ${esc(S.perfil.digitos)}: búscalos en el calendario tributario.`:'Agrega en tu perfil los últimos dígitos de tu cédula para saber tu fecha.'}</div></div></div>
  <div class="card"><h2>Los topes de la DIAN</h2><div class="list">${crit.map(c=>`<div class="rowi" style="align-items:flex-start"><span class="ri ${c.pasa?'t-red':'t-green'}">${ic(c.pasa?'circle-alert':'check')}</span><div class="rb"><div class="rt" style="white-space:normal">${c.l}</div><div class="note" style="white-space:normal">${c.d} Tope: ${NF.format(c.u)} UVT = <b>${$(c.tope)}</b></div><div class="track" style="margin-top:6px"><i style="width:${c.tope?Math.min(c.v/c.tope,1)*100:0}%;background:${c.pasa?'var(--red)':'#9EDB4E'}"></i></div></div><div class="rv">${$(c.v)}</div></div>`).join('')}</div>
    <div class="form">${field('Consignaciones del año (aprox.)',money('rcon',R.consig||'',{attrs:`data-x="rentaF" data-f="consig"`}),{hint:'Suma lo que te entró a tus cuentas.'})}${field('Consumos totales del año (si no los registraste todos)',money('rcons',R.consumos||'',{attrs:`data-x="rentaF" data-f="consumos"`}))}</div></div>
  <section class="grid g2"><div class="card"><h2>Documentos que necesitas (${nd} de ${RDOCS.length})</h2><div class="list">${RDOCS.map(([k,l,d])=>`<label class="rowi" style="align-items:flex-start;cursor:pointer"><input type="checkbox" class="chk" data-x="rentaDoc" data-k="${k}" ${R.docs[k]?'checked':''} style="margin-top:3px"><div class="rb"><div class="rt" style="white-space:normal">${l}</div><div class="note" style="white-space:normal">${d}</div></div></label>`).join('')}</div></div>
  <div class="card"><h2>Datos que ya tengo en el libro</h2><div class="grid g2" style="gap:8px"><div class="metric"><b>${$(ing)}</b><span>Ingresos estimados del año</span></div><div class="metric"><b>${$(T.A)}</b><span>Patrimonio bruto hoy</span></div><div class="metric"><b>${$(T.P)}</b><span>Deudas hoy</span></div><div class="metric"><b>${$(rend)}</b><span>Rendimientos de inversiones</span></div><div class="metric"><b>${$(ret)}</b><span>Retención en la fuente de CDT</span></div><div class="metric"><b>${S.perfil.miembros.filter(m=>/hij/i.test(m.rol)).length}</b><span>Posibles dependientes</span></div></div><p class="note">Los valores del patrimonio y las deudas deben tomarse al 31 de diciembre del año gravable.</p></div></section>`};
