/* ---------------- 10. Gastos compartidos ---------------- */
let GSEL=null;
function balancesGrupo(g){const b={};g.personas.forEach(p=>b[p]=0);g.gastos.forEach(x=>{const ent=x.entre&&x.entre.length?x.entre:g.personas;const parte=x.valor/ent.length;b[x.paga]=(b[x.paga]||0)+ +x.valor;ent.forEach(p=>b[p]=(b[p]||0)-parte)});
  const deu=Object.entries(b).filter(([,v])=>v<-1).map(([p,v])=>[p,-v]).sort((a,c)=>c[1]-a[1]),acr=Object.entries(b).filter(([,v])=>v>1).sort((a,c)=>c[1]-a[1]);const tr=[];let i=0,j=0;while(i<deu.length&&j<acr.length){const m=Math.min(deu[i][1],acr[j][1]);tr.push({de:deu[i][0],a:acr[j][0],v:m});deu[i][1]-=m;acr[j][1]-=m;if(deu[i][1]<1)i++;if(acr[j][1]<1)j++}return{b,tr}}
V.compartidos=()=>{const G=S.grupos;if(!G.find(x=>x.id===GSEL))GSEL=G[0]?.id;const g=G.find(x=>x.id===GSEL);
  let det=empty('split','Crea un grupo para un viaje, la casa con roomies o un regalo entre amigos. Anotan quién pagó qué y te decimos quién le debe a quién.',`<button class="btn pri" data-modal="grupo">${ic('plus')}Crear grupo</button>`);
  if(g){const {b,tr}=balancesGrupo(g),tot=g.gastos.reduce((a,x)=>a+ +x.valor,0);det=`<div class="ph"><h2>${esc(g.nombre)}</h2><div style="display:flex;gap:8px"><button class="btn sm pri" data-modal="gastoGrupo" data-id="${g.id}">${ic('plus')}Gasto</button><button class="btn sm ghost" data-act="delGrupo" data-id="${g.id}" aria-label="Eliminar grupo">${ic('trash-2')}</button></div></div>
    <div class="grid g3" style="gap:8px"><div class="metric"><b>${$(tot)}</b><span>Gastado en total</span></div><div class="metric"><b>${$(tot/(g.personas.length||1))}</b><span>Le toca a cada uno (si es parejo)</span></div><div class="metric"><b>${g.personas.length}</b><span>Personas</span></div></div>
    <h3>Para quedar a paz y salvo</h3>${tr.length?`<div class="list">${tr.map(t=>`<div class="rowi">${av(t.de,'sm')}<div class="rb"><div class="rt">${esc(t.de)} le paga a ${esc(t.a)}</div></div><div class="rv">${$(t.v)}</div></div>`).join('')}</div>`:'<p class="note">Todos están a paz y salvo.</p>'}
    <h3>Cómo va cada uno</h3><div class="list">${Object.entries(b).map(([p,v])=>`<div class="rowi">${av(p,'sm')}<div class="rb"><div class="rt">${esc(p)}</div><div class="rs">${v>1?'Le deben':v<-1?'Debe':'A paz y salvo'}</div></div><div class="rv ${v>1?'pos':v<-1?'neg':''}">${$(Math.abs(v))}</div></div>`).join('')}</div>
    <form data-form="personaGrupo" data-id="${g.id}" style="display:flex;gap:8px"><input class="inp" name="nombre" placeholder="Agregar persona" required><button class="btn">${ic('plus')}Agregar</button></form>
    <h3>Gastos</h3><div class="list">${[...g.gastos].reverse().map(x=>`<div class="rowi"><span class="ri t-gray">${ic('receipt')}</span><div class="rb"><div class="rt">${esc(x.desc)}</div><div class="rs">Pagó ${esc(x.paga)} · entre ${(x.entre&&x.entre.length?x.entre:g.personas).length} · ${fdate(parse(x.fecha))}</div></div><div class="rv">${$(x.valor)}</div><button class="btn icon sm ghost" data-act="delGastoGrupo" data-id="${g.id}" data-gid="${x.id}" aria-label="Eliminar">${ic('trash-2')}</button></div>`).join('')||'<p class="note">Sin gastos todavía.</p>'}</div>`}
  return pageH('split','b-violet','Gastos compartidos','Para viajes, la casa con roomies o un regalo entre varios: anota quién pagó cada cosa y la app calcula quién le debe a quién con el menor número de transferencias.',`<button class="btn pri" data-modal="grupo">${ic('plus')}Nuevo grupo</button>`)+`<section class="grid g12"><div class="card" style="align-self:start"><h2>Grupos</h2><div class="list">${G.map(x=>`<div class="rowi" data-act="selGrupo" data-id="${x.id}" style="cursor:pointer;${x.id===GSEL?'background:var(--blue-soft)':''}"><span class="ri t-violet">${ic('users')}</span><div class="rb"><div class="rt">${esc(x.nombre)}</div><div class="rs">${x.personas.length} personas · ${x.gastos.length} gastos</div></div></div>`).join('')||'<p class="note">Sin grupos.</p>'}</div></div><div class="card">${det}</div></section>`};
M.grupo=()=>({t:'Nuevo grupo de gastos',b:`<form id="mform" data-form="grupo" class="form">${field('Nombre del grupo',txt('nombre','',{req:true,ph:'Ej. Paseo a Villa de Leyva'}),{cls:'full'})}${field('¿Quiénes participan?',txt('personas',(S.perfil.nombre||'Yo').split(' ')[0]+', ',{req:true,ph:'Separa los nombres con comas'}),{cls:'full',hint:'Ej. Alberto, Laura, Andrés'})}</form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Crear</button>`});
M.gastoGrupo=ds=>{const g=S.grupos.find(x=>x.id===ds.id);return{t:'Gasto del grupo',b:`<form id="mform" data-form="gastoGrupo" data-id="${g.id}" class="form">${field('¿Qué se pagó?',txt('desc','',{req:true,ph:'Ej. Hotel'}),{cls:'s2'})}${field('Valor',money('valor','',{req:true}))}${field('¿Quién pagó?',sel('paga',g.personas.map(p=>({v:p,l:p,icon:'user-round'})),g.personas[0]))}${field('Fecha',datep('fecha',iso(today())))}<div class="f full"><span class="fl">¿Entre quiénes se divide?</span><div class="chips">${g.personas.map(p=>`<label class="chip" style="display:inline-flex;gap:6px;align-items:center"><input type="checkbox" class="chk" name="e_${esc(p)}" checked style="width:16px;height:16px">${esc(p)}</label>`).join('')}</div></div><label class="full" style="display:flex;gap:10px;align-items:center;font-size:14.5px"><input type="checkbox" class="switch" name="miGasto">Registrar mi parte en mis gastos</label></form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar</button>`}};
EXTRA_FORM.grupo=d=>{const ps=[...new Set(String(d.personas).split(',').map(x=>x.trim()).filter(Boolean))];if(ps.length<2){toast('Agrega al menos dos personas');return false}S.grupos.push({id:uid(),nombre:d.nombre,personas:ps,gastos:[]});GSEL=S.grupos.at(-1).id;toast('Grupo creado')};
