const HELP={
 puesta:{t:'Puesta en marcha',i:'La guía para configurar tu libro la primera vez.',p:['Sigue los pasos en orden: cada uno abre el formulario que necesitas.','Los pasos opcionales los puedes omitir si no aplican.','Cuando termines, la guía se oculta sola. Puedes volver desde el menú de tu perfil.']},
 inicio:{t:'Inicio',i:'Tu resumen del día: cuánto tienes, cuánto te queda en la quincena y qué pagos se acercan.',p:['Escribe en la caja de arriba lo que gastaste, en palabras ("gasté 15 mil en almuerzo") y la IA lo registra.','Las tarjetas de números muestran tu patrimonio, lo que te queda en la quincena, tus cuotas y los gastos hormiga.','En "Próximos 15 días" puedes pagar o cobrar directamente con los botones de cada fila.'],tips:['Registra tus gastos cada día: toma segundos y es lo que hace que todo funcione.']},
 consejero:{t:'Consejero IA',i:'Antes de comprar, prestar o endeudarte, pregúntale si te alcanza.',p:['Elige qué quieres hacer: comprar, prestar, sacar un crédito o asumir un gasto mensual.','Escribe el valor y, si es a cuotas, cuántas y el interés (o el valor de la cuota).','Toca "Analizar con IA": verás un veredicto (te alcanza, con cuidado o mejor no), las razones y alternativas.'],tips:['Mientras más completos estén tus ingresos, gastos fijos y deudas, más preciso es el consejo.','Puedes cambiar qué tan estricto es en Ajustes › General.']},
 balance:{t:'Balance y quincenas',i:'La Cuenta T muestra lo que tienes (activos) frente a lo que debes (pasivos). Las pestañas de quincena muestran cuánto entra y sale en cada mitad del mes.',p:['En "Lo que tengo y lo que debo" agrega tus cuentas bancarias, efectivo, casa o carro, y deudas sin cuotas.','Los préstamos, inversiones y tarjetas se suman solos desde sus módulos.','En las pestañas de quincena navega entre meses con las flechas.'],tips:['El arriendo o el mercado no van aquí: son gastos. Regístralos en Gastos fijos o Gastos.']},
 ingresos:{t:'Ingresos',i:'Todo el dinero que recibes con regularidad.',p:['Toca "Agregar ingreso" y escribe el concepto y el valor.','Si te pagan por quincena, escribe lo de una quincena y elige "Cada quincena".','Asigna a quién pertenece el ingreso para ver el aporte de cada integrante.'],tips:['Para ingresos de una sola vez (una venta, un bono) escribe en Inicio: "me pagaron 200 mil por…".']},
 gastos:{t:'Gastos y hormiga',i:'Todo lo que gastas, organizado por día. La IA detecta los gastos hormiga: pequeños, frecuentes y evitables.',p:['Toca "Registrar gasto", escribe en qué gastaste: la categoría se pone sola.','También puedes tomarle foto a la factura y la IA llena los datos.','Toca la taza junto a un gasto para marcarlo o desmarcarlo como hormiga.','El botón "Revisar hormiga con IA" revisa todo el mes de una vez.'],tips:['Un tinto diario de $ 5.000 son $ 1.800.000 al año.']},
 fijos:{t:'Gastos fijos',i:'Pagos que se repiten: arriendo, servicios, colegio, administración.',p:['Agrega cada gasto con su día de pago y frecuencia.','Te avisamos unos días antes (lo configuras en Ajustes › Alertas).','Al tocar "Pagar" queda registrado también en tus gastos del mes.'],tips:['Para servicios que cambian cada mes, activa "El valor cambia" y escribe el valor real al pagar.']},
 suscripciones:{t:'Suscripciones',i:'Servicios que se cobran solos cada mes o cada año.',p:['Agrega tus suscripciones con su valor y fecha de cobro.','Revisa las "sugeridas": son cobros que se repiten en tus gastos.','Elimina las que ya no usas para ver cuánto te ahorras al año.']},
 importar:{t:'Importar extractos',i:'Sube el archivo CSV de tu banca en línea y conviértelo en gastos.',p:['Descarga los movimientos de tu banco en formato CSV.','Súbelo o pega su contenido y toca "Leer movimientos".','Revisa la categoría y si es hormiga; luego importa los seleccionados.']},
 correo:{t:'Correo del banco',i:'Lee las notificaciones de compra que tu banco te envía al Gmail.',p:['Toca "Buscar compras en mi correo".','La IA saca comercio, valor y fecha de cada correo.','Marca los que quieres registrar y confirma. Los correos ya importados no se repiten.']},
 tarjetas:{t:'Tarjetas de crédito',i:'Controla cupo, fechas y el costo real de diferir compras.',p:['Agrega tu tarjeta con su cupo, día de corte, día de pago e interés mensual.','Registra cada compra con el número de cuotas.','Usa la calculadora antes de comprar para ver cuánto pagas en intereses según las cuotas.'],tips:['Diferir a 1 cuota y pagar el total cada mes evita los intereses.']},
 'me-deben':{t:'Me deben',i:'Personas o clientes a quienes les prestaste dinero.',p:['Toca "Nuevo préstamo", elige o crea el contacto y escribe el valor y las cuotas.','Si no sabes la tasa, escribe cuánto es cada cuota y calculamos el interés.','Cuando te paguen, toca "Registrar pago recibido": cuota completa o abono.','Usa "Enviar recordatorio" para cobrar por WhatsApp o correo, y "Acuerdo de pago" para generar el documento en PDF.']},
 'le-debo':{t:'Le debo',i:'Tus créditos con bancos y deudas con personas.',p:['Registra la deuda con el banco o la persona, el valor, las cuotas y la tasa.','Agrega los seguros que te cobran en cada cuota para que el valor coincida con tu extracto.','Registra cada pago o abono para saber cuánto te falta.'],tips:['Un abono para "terminar antes" casi siempre ahorra más intereses que bajar la cuota.']},
 contactos:{t:'Contactos',i:'Las personas y empresas con quienes tienes préstamos.',p:['Guarda nombre, documento, celular, correo y dirección una sola vez.','Al registrar un préstamo, solo eliges el contacto.','En cada tarjeta ves cuánto te debe y cuánto le debes.']},
 estrategia:{t:'Salir de deudas',i:'Compara dos métodos para pagar tus deudas más rápido con un pago extra.',p:['Escribe cuánto más puedes pagar cada mes.','Mira cuántos meses y cuánto interés ahorras con cada método.','Simula un abono a un crédito y elige entre terminar antes o bajar la cuota.']},
 presupuesto:{t:'Presupuesto 50/30/20',i:'La regla más usada: 50% necesidades, 30% gustos, 20% ahorro.',p:['Escribe el tope mensual de cada categoría.','El semáforo te muestra si vas bien, cerca del tope o te pasaste.','Cambia los porcentajes en Ajustes › Finanzas.']},
 flujo:{t:'Flujo de caja',i:'Proyección de los próximos 12 meses: cuánto entra, cuánto sale y con cuánto quedas.',p:['Revisa los meses en rojo: ahí te faltaría plata.','Para que sea preciso, mantén al día ingresos, gastos fijos, deudas y presupuesto.','Escribe el valor de primas y cesantías en el calendario para que se sumen en su mes.']},
 metas:{t:'Metas y emergencia',i:'Ponle nombre y fecha a lo que quieres lograr.',p:['Crea una meta con el valor y la fecha.','Te decimos cuánto guardar al mes.','Registra cada abono para ver tu avance.'],tips:['Primero arma tu fondo de emergencia: de 3 a 6 meses de gastos básicos.']},
 familia:{t:'Por miembro',i:'Cupo y gastos de cada integrante de la familia.',p:['Agrega los integrantes en tu perfil.','Escribe el cupo mensual de cada uno.','Al registrar gastos elige quién gastó para ver el avance.']},
 retos:{t:'Retos de ahorro',i:'Desafíos para cambiar hábitos.',p:['Elige un reto de la lista.','Los retos "sin" se revisan solos con tus gastos.','En los retos de ahorro, marca cada día o semana cuando guardes el dinero.']},
 primas:{t:'Primas y cesantías',i:'Planea en qué usar tus primas y cesantías antes de recibirlas.',p:['Revisa tu salario (lo tomamos de tus ingresos).','Mueve los porcentajes para repartir la prima.','Pídele un plan a la IA o pon los valores en el calendario.']},
 compartidos:{t:'Gastos compartidos',i:'Divide cuentas de viajes, la casa o regalos entre varias personas.',p:['Crea un grupo con los nombres de los participantes.','Anota cada gasto: quién pagó y entre quiénes se divide.','Mira "Para quedar a paz y salvo": quién le paga a quién.']},
 mesadas:{t:'Mesada de los hijos',i:'Una cuenta sencilla para enseñarles a manejar el dinero.',p:['Agrega a tus hijos como integrantes en tu perfil.','Define la mesada y entrégala con un toque.','Anoten juntos sus gastos y su meta de ahorro.']},
 inversiones:{t:'Inversiones',i:'Mira cuánto crece tu dinero, explicado sin palabras raras.',p:['Toca "Agregar inversión" y elige dónde pusiste el dinero.','Para CDT y cuentas que rinden, escribe la tasa E.A.: calculamos lo que ganas.','Para fondos o acciones, actualiza el valor cuando revises tu extracto.']},
 recordatorios:{t:'Próximos pagos',i:'Todo lo que debes pagar o cobrar, ordenado por fecha.',p:['Paga o cobra con los botones de cada fila.','Agrega los pagos a tu Google Calendar con un toque.','Los vencidos aparecen arriba en rojo.']},
 calendario:{t:'Calendario fiscal',i:'Fechas anuales: primas, cesantías, renta, predial, impuesto vehicular.',p:['Ajusta las fechas de impuestos a las de tu ciudad y tu cédula.','Escribe el valor estimado para que se sume en el flujo de caja.','Toca "Recordar" para crear un gasto fijo anual con aviso.']},
 indicadores:{t:'Salud financiera',i:'Seis preguntas para saber si tus finanzas están sanas.',p:['Cada indicador muestra un semáforo y su meta.','Si faltan datos, te dice cuáles y te lleva a completarlos.','El puntaje general aparece con al menos 4 indicadores.']},
 reportes:{t:'Reportes',i:'Balance y resultado del mes para revisar en familia.',p:['Elige el mes.','Genera el resumen con IA para entender en qué se fue la plata.','Descarga el PDF o los movimientos en CSV para Excel.']},
 renta:{t:'Asistente de renta',i:'Te dice si debes declarar renta y qué documentos reunir.',p:['Elige el año gravable y verifica el valor de la UVT.','Completa las consignaciones del año.','Marca los documentos a medida que los consigas.'],tips:['Es una orientación. Para presentar la declaración apóyate en un contador o en el asistente de la DIAN.']},
 perfil:{t:'Perfil',i:'Tus datos y los de tu familia.',p:['Completa tu nombre, ciudad y documento (se usan en los acuerdos de pago).','Agrega a los integrantes de la familia y su cupo.']},
 ajustes:{t:'Ajustes',i:'Personaliza el libro.',p:['General: tema, privacidad, IA y pantalla de inicio.','Alertas: qué te avisamos y con cuánta anticipación.','Finanzas: quincenas, porcentajes, monedas y usura.','Listas: categorías, bancos, medios de pago, relaciones y reglas.','Datos y cuenta: respaldos, formatear y eliminar.']}};
const helpSeen=()=>store.get('lmf-ayuda-vista',{});
function helpStrip(v){const h=HELP[v];if(!h||helpSeen()[v])return'';return `<div class="alert info" style="background:var(--blue-soft)"><span class="ai">${ic('lightbulb')}</span><div><b>¿Para qué sirve esta sección?</b>${esc(h.i)} <a href="#" data-act="help" style="font-weight:600">Ver cómo se usa</a></div><button class="btn sm ghost" data-act="helpHide" data-v="${v}" style="align-self:center">Entendido</button></div>`}
M.help=ds=>{const v=ds.v||view();const h=HELP[v]||{t:'Ayuda',i:'',p:[]};return{t:'Cómo usar: '+h.t,b:`<p style="margin:0;font-size:15px">${esc(h.i)}</p><div class="list" style="margin:0">${h.p.map((x,i)=>`<div class="rowi" style="align-items:flex-start"><span class="ri t-green" style="width:30px;height:30px;font-weight:800">${i+1}</span><div class="rb"><div style="white-space:normal;font-size:14.5px">${esc(x)}</div></div></div>`).join('')}</div>${(h.tips||[]).map(t=>alertBox('ok','lightbulb','Consejo',esc(t))).join('')}`,f:`<button class="btn" data-act="tourStart">${ic('map')}Hacer el tour de la plataforma</button><button class="btn pri" data-act="mclose">Entendido</button>`}};
EXTRA_ACT.help=()=>{openModal('help',{v:view()})};
EXTRA_ACT.helpHide=b=>{const s=helpSeen();s[b.dataset.v]=1;store.set('lmf-ayuda-vista',s);render()};
EXTRA_ACT.helpReset=()=>{store.set('lmf-ayuda-vista',{});toast('Las explicaciones volverán a aparecer');render()};

/* ---- tour guiado ---- */
const TOUR=[{sel:'#side',t:'El menú',d:'Aquí están todas las secciones, agrupadas. Toca un grupo para ver sus opciones. Lo puedes contraer con Ctrl+B.'},{sel:'.sb-brand',t:'Tus libros',d:'Cambia entre tus libros (por ejemplo, el hogar y tu negocio) o crea uno nuevo.'},{sel:'.sb-search',t:'Buscador',d:'Encuentra secciones, contactos, préstamos o gastos fijos escribiendo su nombre. Atajo: Ctrl+K.'},{sel:'#crumbs',t:'Dónde estás',d:'Esta ruta te muestra en qué libro y sección te encuentras.'},{sel:'.composer',t:'Registra en palabras',d:'En Inicio escribe lo que gastaste o recibiste, como lo dirías: la IA lo entiende y lo registra.'},{sel:'.sb-create',t:'Agregar',d:'Registra rápidamente un gasto, ingreso, préstamo, deuda, contacto, inversión o meta.'},{sel:'#bell',t:'Notificaciones',d:'Te avisamos de pagos por vencer, cobros atrasados, gastos hormiga y más.'},{sel:'.sb-tog',t:'Contraer el menú',d:'Hazlo más angosto para ganar espacio (Ctrl+B). Ocultar montos y el tema oscuro están en tu menú de usuario, abajo.'},{sel:'#asFab',t:'Chat con Mirai',d:'Este globo abre el chat: pregunta lo que quieras sobre tu plata. Lo puedes arrastrar a donde te estorbe menos.'},{sel:'.sb-user',t:'Tu menú',d:'Perfil, ajustes, tema oscuro, respaldo y la puesta en marcha.'},{sel:'.page-h .help-btn',t:'Cómo funciona',d:'En cada sección encontrarás este botón con el paso a paso para usarla.'}];
let TI=-1;
function tourShow(){let el=null;while(TI<TOUR.length){el=document.querySelector(TOUR[TI].sel);if(el&&el.offsetParent!==null)break;TI++}if(TI>=TOUR.length){tourEnd();return}
  let ov=document.getElementById('tour');if(!ov){ov=document.createElement('div');ov.id='tour';document.body.appendChild(ov)}const r=el.getBoundingClientRect(),s=TOUR[TI];const pad=6;
  const boxW=Math.min(320,window.innerWidth-24);let left=r.right+14,top=r.top;if(left+boxW>window.innerWidth-12){left=Math.max(12,Math.min(r.left,window.innerWidth-boxW-12));top=r.bottom+14}if(top+190>window.innerHeight)top=Math.max(12,r.top-200);
  ov.innerHTML=`<div class="tour-ring" style="left:${r.left-pad}px;top:${r.top-pad}px;width:${r.width+pad*2}px;height:${Math.min(r.height+pad*2,window.innerHeight-20)}px"></div><div class="tour-card" role="dialog" style="left:${left}px;top:${top}px;width:${boxW}px"><div class="lbl-s">Paso ${TI+1} de ${TOUR.length}</div><h3 style="margin:2px 0 6px;font-size:17px">${s.t}</h3><p style="margin:0 0 12px;font-size:14px;color:var(--muted)">${s.d}</p><div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn sm ghost" data-act="tourEnd">Saltar</button>${TI>0?`<button class="btn sm" data-act="tourPrev">Anterior</button>`:''}<button class="btn sm pri" data-act="tourNext">${TI===TOUR.length-1?'Terminar':'Siguiente'}</button></div></div>`}
function tourEnd(){TI=-1;document.getElementById('tour')?.remove();store.set('lmf-tour',1)}
EXTRA_ACT.tourStart=()=>{closeModal();closePop();if(window.innerWidth<=820&&!document.body.classList.contains('nav-open')){}document.body.classList.remove('sb-col');renderNav(view());TI=0;window.scrollTo(0,0);setTimeout(tourShow,120)};
EXTRA_ACT.tourNext=()=>{TI++;tourShow()};EXTRA_ACT.tourPrev=()=>{TI=Math.max(0,TI-1);while(TI>0&&!document.querySelector(TOUR[TI].sel))TI--;tourShow()};EXTRA_ACT.tourEnd=()=>tourEnd();
window.addEventListener('resize',()=>{if(TI>=0)tourShow()});

function openSearchModal(){openModal('buscar')}
M.buscar=()=>({t:'Buscar',b:`<label class="search" style="display:flex;width:100%;height:40px;border:1px solid var(--line);border-radius:8px;padding:0 10px">${ic('search')}<input id="q2" placeholder="Sección, contacto, préstamo…" autocomplete="off" style="border:0;outline:0;background:transparent;font:inherit;color:var(--ink);width:100%"></label><div class="list" id="q2r"></div>`});
document.addEventListener('input',e=>{if(e.target.id!=='q2')return;const q=e.target.value.trim().toLowerCase();const res=[];MENUPAGES().filter(p=>p[1].toLowerCase().includes(q)).forEach(p=>res.push([p[0],p[1],p[2]]));S.contactos.filter(c=>c.nombre.toLowerCase().includes(q)).forEach(c=>res.push(['contactos',c.nombre,'user-round']));document.getElementById('q2r').innerHTML=q?res.slice(0,10).map(r=>`<div class="opt" data-go="${r[0]}" data-close="1"><span class="oi">${ic(r[2])}</span>${esc(r[1])}</div>`).join('')||'<p class="note">Sin resultados</p>':''});

/* ---- cajón de apps de la suite ---- */
function defApps(){return[['Gmail','https://mail.google.com','correo','Correo'],['Calendar','https://calendar.google.com','calendario','Agenda'],['Drive','https://drive.google.com','importar','Documentos'],['Claude','https://claude.ai','consejero','Asistente IA'],['DIAN','https://www.dian.gov.co','renta','Impuestos'],['Mi banco','','le-debo','Agrega el enlace de tu banca en línea']].map(([nombre,url,icon,desc])=>({id:uid(),nombre,url,icon,desc}))}
const APP_ICONS=Object.keys(ISO).filter(k=>k!=='mirai');
let APPEDIT=false;
function drawApps(){const apps=S.cfg.apps||[];POP.innerHTML=`<div class="launcher"><div class="ln-h">${isoIcon('mirai',28)}<b>Apps</b><button class="btn sm ghost" data-act="appEdit" style="margin-left:auto">${APPEDIT?'Listo':'Editar'}</button></div>
  <a class="ln-cur" href="#inicio" data-act="appClose">${isoIcon('mirai',40)}<div><b>Mirai Finanzas</b><span class="note">Estás aquí</span></div></a>
  <div class="ln-sec">Tus apps</div><div class="ln-grid">${apps.map(a=>{const inner=`${isoIcon(a.icon,40)||isoIcon('mirai',40)}<span>${esc(a.nombre)}</span>`;return APPEDIT?`<div class="ln-app edit">${inner}<button class="ln-x" data-act="appDel" data-id="${a.id}" aria-label="Quitar ${esc(a.nombre)}">${ic('x')}</button><button class="btn sm ghost" data-modal="appNew" data-id="${a.id}" style="height:24px;font-size:12px">Editar</button></div>`:a.url?`<a class="ln-app" href="${esc(a.url)}" target="_blank" rel="noopener" title="${esc(a.desc||a.url)}">${inner}</a>`:`<button class="ln-app dim" data-modal="appNew" data-id="${a.id}" title="Agrega el enlace">${inner}</button>`}).join('')}<button class="ln-app add" data-modal="appNew">${ic('plus')}<span>Agregar app</span></button></div>
  <p class="note" style="margin-top:10px">Accesos directos a las apps que usas junto con Mirai. Se abren en una pestaña nueva.</p></div>`}
EXTRA_ACT.launcher=b=>{if(POPC&&POPC.type==='launcher'){closePop();return}closePop();APPEDIT=false;POPC={type:'launcher',btn:b};drawApps();POP.hidden=false;POP.style.minWidth='0';POP.style.left='8px';POP.style.top=(b.getBoundingClientRect().bottom+6)+'px'};
EXTRA_ACT.appEdit=()=>{APPEDIT=!APPEDIT;drawApps()};EXTRA_ACT.appClose=()=>closePop();
EXTRA_ACT.appDel=b=>{S.cfg.apps=S.cfg.apps.filter(a=>a.id!==b.dataset.id);commit();drawApps()};
M.appNew=ds=>{const a=(S.cfg.apps||[]).find(x=>x.id===ds.id)||{icon:'inversiones'};return{t:a.id?'Editar app':'Agregar app al cajón',b:`<form id="mform" data-form="appNew" data-id="${a.id||''}" class="form">${field('Nombre',txt('nombre',a.nombre,{req:true,ph:'Ej. Mi banco'}))}${field('Enlace',txt('url',a.url,{type:'url',req:true,ph:'https://…'}),{hint:'La dirección web de la app. Debe empezar por https://'})}${field('Descripción corta',txt('desc',a.desc,{ph:'Ej. Banca en línea'}),{cls:'full'})}<div class="f full"><span class="fl">Ícono</span><div class="ln-grid icons">${APP_ICONS.map(k=>`<button type="button" class="ln-app ${k===a.icon?'on':''}" data-pick="icon" data-v="${k}" title="${k}">${isoIcon(k,32)}</button>`).join('')}</div>${hidden('icon',a.icon)}</div></form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar</button>`}};
EXTRA_FORM.appNew=(d,f)=>{if(!/^https:\/\//i.test(String(d.url).trim())){toast('El enlace debe empezar por https://');return false}const o={nombre:d.nombre.trim(),url:String(d.url).trim(),desc:d.desc,icon:d.icon||'inversiones'};const ex=S.cfg.apps.find(x=>x.id===f.dataset.id);if(ex)Object.assign(ex,o);else S.cfg.apps.push({id:uid(),...o});toast('App guardada en el cajón')};
